const allItems = [];

// Helper: extract from HTML using regex (simplifié - adapter selon structure réelle)
function extractFromHTML(html, source) {
  const items = [];
  // Patterns génériques - À ADAPTER par site
  const patterns = {
    title: /<h3[^>]*class="[^"]*title[^"]*"[^>]*>([^<]+)</gi,
    reference: /(?:Réf|Ref|N°)[\s:]*([A-Z0-9\-\/]+)/gi,
    deadline: /(?:Date limite|Échéance|Clôture)[\s:]*([0-9]{1,2}[\/\-][0-9]{1,2}[\/\-][0-9]{2,4})/gi,
    amount: /(?:Montant|Budget|Estimation)[\s:]*([0-9\s,.]+\s*(?:FCFA|CFA|XOF|€|EUR))/gi,
    category: /(?:Catégorie|Secteur|Domaine)[\s:]*([^<]+)/gi,
    link: /<a[^>]+href="([^"]+)"[^>]*>.*?(?:Voir|Détail|Dossier)/gi
  };

  let match;
  while ((match = patterns.title.exec(html)) !== null) {
    const idx = items.length;
    items.push({
      source,
      title: match[1].trim(),
      reference: '',
      deadline: '',
      amount: '',
      category: '',
      link: '',
      detectedAt: new Date().toISOString(),
      rawHtml: html.substring(match.index, match.index + 2000)
    });
  }
  // Enrichir chaque item avec autres patterns (simplifié)
  return items;
}

// Process each source
const sources = [
  {name: 'TG', data: items[0].json},
  {name: 'SN', data: items[1].json},
  {name: 'CI', data: items[2].json},
  {name: 'BF', data: items[3].json},
  {name: 'ML', data: items[4].json},
  {name: 'BOAD', data: items[5].json},
  {name: 'TELCO', data: items[6].json},
  {name: 'BANKS', data: items[7].json},
  {name: 'DONORS', data: items[8].json}
];

sources.forEach(s => {
  if (s.data?.html) {
    allItems.push(...extractFromHTML(s.data.html, s.name));
  } else if (s.data?.data) {
    // API JSON response
    allItems.push(...s.data.data.map(d => ({
      source: s.name,
      title: d.title || d.objet || d.libelle,
      reference: d.reference || d.numero || d.ref,
      deadline: d.dateLimite || d.echeance || d.cloture,
      amount: d.montant || d.budget || d.estimation,
      category: d.categorie || d.secteur || d.domaine,
      link: d.url || d.lien || d.detailUrl,
      detectedAt: new Date().toISOString()
    })));
  }
});

return allItems.map(item => ({json: item}));

const keywords = [
  // Tes secteurs cibles - ADAPTER
  'informatique', 'numérique', 'digital', 'logiciel', 'développement',
  'télécom', 'réseau', 'fibre', 'connectivité', 'infrastructure',
  'énergie', 'solaire', 'électrique', 'groupe électrogène',
  'construction', 'bâtiment', 'travaux', 'génie civil', 'voirie',
  'fourniture', 'équipement', 'matériel', 'fournitures bureau',
  'service', 'prestation', 'conseil', 'formation', 'maintenance',
  'sécurité', 'surveillance', 'gardiennage', 'incendie',
  'nettoyage', 'hygiène', 'environnement', 'déchet',
  'transport', 'logistique', 'livraison', 'fret',
  'santé', 'médical', 'pharmacie', 'laboratoire', 'hôpital',
  'éducation', 'université', 'école', 'formation professionnelle',
  'agricole', 'intrant', 'engrais', 'semence', 'machinisme',
  'eau', 'assainissement', 'forage', 'adduction',
  'banque', 'finance', 'assurance', 'microfinance',
  'état', 'ministère', 'direction', 'agence', 'office', 'commune'
];

const excludeKeywords = [
  'architecte', 'maître d\'œuvre', 'bureau d\'études', 'géotechnique',
  'topographe', 'arpenteur', 'notaire', 'huissier', 'avocat',
  'expertise comptable', 'commissaire aux comptes', 'audit financier'
];

const today = new Date();
const thirtyDays = new Date(today.getTime() + 30*24*60*60*1000);

return items.filter(item => {
  const text = (item.json.title + ' ' + (item.json.category || '')).toLowerCase();

  // Exclusion
  if (excludeKeywords.some(k => text.includes(k))) return false;

  // Inclusion (au moins 1 mot-clé)
  if (!keywords.some(k => text.includes(k))) return false;

  // Échéance > aujourd'hui et < 30 jours
  let deadline;
  try {
    const parts = item.json.deadline.split(/[\/\-]/);
    if (parts.length === 3) {
      deadline = new Date(parts[2], parts[1]-1, parts[0]);
    }
  } catch (e) { return false; }

  if (!deadline || deadline < today || deadline > thirtyDays) return false;

  // Montant > 5M FCFA (seuil intéressant)
  let amount = 0;
  if (item.json.amount) {
    const match = item.json.amount.match(/([0-9\s,.]+)/);
    if (match) amount = parseFloat(match[1].replace(/[\s,]/g, '').replace('.', ''));
    if (item.json.amount.includes('M') || item.json.amount.includes('milliard')) amount *= 1000000;
    else if (item.json.amount.includes('k') || item.json.amount.includes('million')) amount *= 1000;
  }
  if (amount < 5000000) return false;

  item.json.parsedAmount = amount;
  item.json.parsedDeadline = deadline.toISOString().split('T')[0];
  item.json.score = calculateScore(item.json);

  return true;
});

function calculateScore(item) {
  let score = 50;
  const text = (item.title + ' ' + (item.category || '')).toLowerCase();

  // Bonus secteurs cœur de cible
  if (text.includes('informatique') || text.includes('numérique') || text.includes('digital')) score += 30;
  if (text.includes('énergie') || text.includes('solaire')) score += 25;
  if (text.includes('construction') || text.includes('travaux')) score += 20;

  // Bonus montant
  if (item.parsedAmount > 100000000) score += 20;
  else if (item.parsedAmount > 50000000) score += 15;
  else if (item.parsedAmount > 20000000) score += 10;

  // Bonus échéance proche (urgent = moins de concurrence)
  const daysLeft = (new Date(item.parsedDeadline) - new Date()) / (1000*60*60*24);
  if (daysLeft < 10) score += 15;
  else if (daysLeft < 20) score += 10;

  // Bonus source fiable
  if (['TG', 'SN', 'CI', 'BOAD'].includes(item.source)) score += 10;

  return Math.min(100, score);
}

